// Готовая сборка композиции для движка рендера: кладется в программу, пользователю не нужен сборщик.
//   node scripts/build-render-bundle.mjs

import { cpSync, rmSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { bundle } from "@remotion/bundler";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const out = resolve(root, "src-tauri/resources/render-bundle");
const built = await bundle({
  entryPoint: resolve(root, "src/render/entry.tsx"),
  webpackOverride: (config) => ({ ...config, resolve: { ...config.resolve, alias: { ...config.resolve?.alias, "@": resolve(root, "src") } } }),
});
rmSync(out, { recursive: true, force: true });
cpSync(built, out, { recursive: true });
console.log(`render bundle: ${out}`);
writeFileSync(resolve(out, "README.txt"), "Generated by scripts/build-render-bundle.mjs before a release build.\n");
